TextButton15.MouseButton1Click:Connect(function()
	SakuraUISound8.Volume = 1.575
	SakuraUISound8.TimePosition = 0
	SakuraUISound8:Play()
	RunService:UnbindFromRenderStep("SakuraMotionBlur")
	local SakuraMotionBlur = Instance.new("BlurEffect")
	SakuraMotionBlur.Name = "SakuraMotionBlur"
	SakuraMotionBlur.Size = 0
	SakuraMotionBlur.Size = 0
	SakuraMotionBlur.Enabled = true
	SakuraMotionBlur.Parent = Lighting

	local lastSakuraCamPos = nil
	RunService:BindToRenderStep("SakuraMotionBlur", 220, function(delta)
		local cam = workspace.CurrentCamera
		if not cam then return end
		local pos = cam.CFrame.Position
		if lastSakuraCamPos and delta and delta > 0 then
			local speed = (pos - lastSakuraCamPos).Magnitude / delta
			local target = math.clamp(speed / 8, 0, 24)
			SakuraMotionBlur.Size = SakuraMotionBlur.Size + (target - SakuraMotionBlur.Size) * math.clamp(delta * 10, 0, 1)
		end
		lastSakuraCamPos = pos
	end)

	local tween654 = TweenService:Create(Frame57, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundColor3 = Color3.fromRGB(150, 108, 255) })
	tween654:Play()
	local tween655 = TweenService:Create(Frame58, TweenInfo.new(0.32, Enum.EasingStyle.Back, Enum.EasingDirection.Out), { BackgroundColor3 = Color3.new(1, 1, 1), Position = UDim2.new(0, 21, 0.5, 0) })
	tween655:Play()
	local tween656 = TweenService:Create(UIStroke16, TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Transparency = 0.25 })
