task.spawn(function()
	task.wait(0.5)
	Players.LocalPlayer.Character:WaitForChild("Humanoid", 5)
	local HumanoidRootPart = Players.LocalPlayer.Character:WaitForChild("HumanoidRootPart", 5)
	local TrailBottom = HumanoidRootPart:FindFirstChild("TrailBottom")
	TrailBottom:Destroy()
	local TrailTop = HumanoidRootPart:FindFirstChild("TrailTop")
	TrailTop:Destroy()
	local SakuraFireTrail = HumanoidRootPart:FindFirstChild("SakuraFireTrail")
	SakuraFireTrail:Destroy()
	local TrailBottom3 = Instance.new("Attachment", HumanoidRootPart)
	TrailBottom3.Name = "TrailBottom"
	TrailBottom3.Position = Vector3.new(0, -2.5, 0)
	local TrailTop3 = Instance.new("Attachment", HumanoidRootPart)
	TrailTop3.Name = "TrailTop"
